export function validPatterns(lesson, prefix){ return lesson.patterns.filter(p=>p.startsWith(prefix)); }
export function tokens(text){return text.toLocaleLowerCase('de').match(/[\p{L}\p{M}]+(?:['’][\p{L}]+)?/gu)||[];}
export function analyze(text,term=''){
 const words=tokens(text),freq=new Map(); for(const w of words)freq.set(w,(freq.get(w)||0)+1);
 const sequences=[];for(let n=3;n<=6;n++){const m=new Map();for(let i=0;i<=words.length-n;i++){const s=words.slice(i,i+n).join(' ');m.set(s,(m.get(s)||0)+1)}for(const [s,c]of m)if(c>1)sequences.push([s,c]);}
 const q=tokens(term)[0];const kwic=q?words.flatMap((w,i)=>w===q?[{left:words.slice(Math.max(0,i-4),i).join(' '),word:w,right:words.slice(i+1,i+5).join(' ')}]:[]):[];
 return {words:words.length,types:freq.size,lines:text.split('\n').filter(x=>x.trim()).length,freq:[...freq].sort((a,b)=>b[1]-a[1]).slice(0,12),ngrams:sequences.sort((a,b)=>b[1]-a[1]).slice(0,10),kwic};
}
export function generatePoem(words,random=Math.random){const pick=a=>a[Math.min(a.length-1,Math.floor(random()*a.length))];const [objects,feelings,actions]=words.map(x=>x.split(',').map(s=>s.trim()).filter(Boolean));if(!objects.length||!feelings.length||!actions.length)throw Error('Fülle alle drei Wortfelder aus.');const object=pick(objects),feeling=pick(feelings),action=pick(actions);return `du nennst es ${object}.\nich nenne es ${feeling}.\n\nich will ${action},\nauch wenn der morgen schweigt.\n\nvielleicht beginnt es hier:\nbei einem wort,\ndas bleibt.`;}
export function validateSave(v){return v&&v.version===1&&Array.isArray(v.done)&&v.done.every(x=>['ankommen','lesen','hoeren','rhythmus','werkstatt'].includes(x))&&v.notes&&typeof v.notes==='object'&&!Array.isArray(v.notes)&&Object.values(v.notes).every(x=>typeof x==='string'&&x.length<200000)&&v.done.length<=5;}
